import json
import sys
from pathlib import Path

repo = Path.cwd()
sys.path.insert(0, str(repo / "src"))

from do_again.browser import cdp
from do_again.browser.runtime import browser_status, project_record, _find_chatgpt_target, wait_for_authenticated

record = project_record(repo)
status = browser_status()
port = int(status["port"])
target = _find_chatgpt_target(port, str(record.get("chat_url") or ""))
if target is None:
    raise SystemExit("bound target not found")
target, _ = wait_for_authenticated(port, chat_url=target.url, timeout=30.0, target=target)

marker = "DO_AGAIN_RECEIPT_READY request_id=live-e2e-inspect-9c41f0f2e3ab"
expr = """(() => {
const marker = %s;
const all = Array.from(document.querySelectorAll('body *'));
const hits = all.filter(el => ((el.innerText || el.textContent || '')).includes(marker));
return hits.slice(0, 30).map(el => {
  const chain = [];
  let cur = el;
  for (let i = 0; cur && i < 8; i++, cur = cur.parentElement) {
    chain.push({
      tag: cur.tagName,
      id: cur.id || null,
      cls: typeof cur.className === 'string' ? cur.className.slice(0, 300) : null,
      testid: cur.getAttribute && cur.getAttribute('data-testid'),
      role: cur.getAttribute && cur.getAttribute('data-message-author-role'),
      convo: cur.getAttribute && cur.getAttribute('data-conversation-role'),
      aria: cur.getAttribute && cur.getAttribute('aria-label'),
      text: (cur.innerText || cur.textContent || '').slice(0, 500)
    });
  }
  return chain;
});
})()""" % json.dumps(marker)

result = cdp.evaluate(target, expr, timeout=20.0)
print(json.dumps({"chat_url": target.url, "marker": marker, "hits": result}, indent=2))
